BEGIN;
CREATE TABLE IF NOT EXISTS teacher_departments(teacher_id BIGINT REFERENCES users, department_id BIGINT REFERENCES departments, PRIMARY KEY(teacher_id,department_id));
CREATE TABLE IF NOT EXISTS office_hours(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, teacher_id BIGINT NOT NULL REFERENCES users, weekday INTEGER NOT NULL CHECK(weekday BETWEEN 1 AND 7), starts_at TIME NOT NULL, ends_at TIME NOT NULL, location TEXT NOT NULL, CHECK(ends_at>starts_at));
CREATE TABLE IF NOT EXISTS program_courses(program_id BIGINT REFERENCES programs, course_id BIGINT REFERENCES courses, year_level INTEGER NOT NULL CHECK(year_level BETWEEN 1 AND 8), PRIMARY KEY(program_id,course_id));
CREATE TABLE IF NOT EXISTS import_jobs(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, actor_id BIGINT REFERENCES users, row_count INTEGER NOT NULL, state TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
ALTER TABLE scores ADD COLUMN IF NOT EXISTS raw_points NUMERIC(8,2);
ALTER TABLE scores ADD COLUMN IF NOT EXISTS late_penalty NUMERIC(8,2) NOT NULL DEFAULT 0;
COMMIT;
